<script setup lang="ts">import type{StepControl}from'../../types/protocol';defineProps<{control:StepControl}>();defineEmits<{toggle:[number]}>()</script><template><div class="steps" :aria-label="control.label"><button v-for="(on,i) in control.steps" :key="i" :disabled="control.read_only" :class="{on,play:i===control.position}" :aria-pressed="on" @click="$emit('toggle',i)">{{i+1}}</button></div></template>
